function addVectors(a, b) {
  return a.map((x, i) => x + b[i]);
}

function scaleVector(v, s) {
  return v.map((x) => x * s);
}

function dot(a, b) {
  return a.reduce((sum, x, i) => sum + x * b[i], 0);
}

function subtractVectors(a, b) {
  return a.map((x, i) => x - b[i]);
}

function firstOutput(matrix, v) {
  const row = matrix[0];
  return row.reduce((sum, a, i) => sum + a * v[i], 0);
}

function weightedTotal(weights, quantities) {
  return weights.reduce((sum, w, i) => sum + w * quantities[i], 0);
}

function matVec(matrix, v) {
  return matrix.map((row) => row.reduce((sum, a, i) => sum + a * v[i], 0));
}

function applyInOrder(first, second, v) {
  const mv = (m, x) => m.map((row) => row.reduce((s, a, i) => s + a * x[i], 0));
  return mv(second, mv(first, v));
}

function costAndWeight(prices, quantities) {
  const ones = quantities.map(() => 1);
  const rows = [ones, prices];
  return rows.map((row) => row.reduce((sum, a, i) => sum + a * quantities[i], 0));
}
